mapper.select:
SELECT ck.id, ck.check_time AS checkTime, ck.method,
       stu.name AS userName, c.name AS courseName, s.start_time AS startTime
FROM checkin ck
LEFT JOIN `user` stu ON stu.id = ck.user_id
LEFT JOIN course_schedule s ON s.id = ck.schedule_id
LEFT JOIN course c ON c.id = s.course_id
WHERE ck.store_id = #{storeId}
AND ck.check_time >= #{from}
AND ck.check_time < #{to}
AND ck.schedule_id = #{scheduleId}
ORDER BY ck.check_time DESC

SELECT
  (SELECT COUNT(*) FROM checkin ck WHERE ck.store_id = #{storeId}
     AND ck.check_time >= #{from}
     AND ck.check_time < #{to}) AS checkinCount,
  (SELECT COUNT(*) FROM booking b JOIN course_schedule s ON s.id=b.schedule_id
     WHERE b.store_id = #{storeId} AND b.status IN ('booked','checked','noshow')
     AND s.start_time >= #{from}
     AND s.start_time < #{to}) AS bookingCount,
  (SELECT COUNT(*) FROM booking b JOIN course_schedule s ON s.id=b.schedule_id
     WHERE b.store_id = #{storeId} AND b.status = 'noshow'
     AND s.start_time >= #{from}
     AND s.start_time < #{to}) AS noshowCount
